import struct

try:
    from cStringIO import StringIO as BytesIO
except ImportError:
    from io import BytesIO
from gzip import GzipFile

import six


# Notes on GzipFile behaviour across versions:
# - Python>=3.5 GzipFile's read() has issues returning leftover
#   uncompressed data when input is corrupted
#   (regression or bug-fix compared to Python 3.4)
# - read1(), which fetches data before raising EOFError on next call
#   works here but is only available from Python>=3.3
# - scrapy does not support Python 3.2
# - Python 2.7 GzipFile works fine with standard read() + extrabuf
if six.PY2:
    def _fetch(gzf, size=-1):
        return gzf.read(size)
else:
    def _fetch(gzf, size=-1):
        return gzf.read1(size)


def gunzip(data):
    """Gunzip the given data and return as much data as possible.

    This is resilient to CRC checksum errors.
    """
    stream = GzipFile(fileobj=BytesIO(data))
    result = b''
    block = b'.'
    while block:
        try:
            block = _fetch(stream, 8196)
            result = result + block
        except (IOError, EOFError, struct.error):
            # complete only if there is some data, otherwise re-raise
            # see issue 87 about catching struct.error
            # some pages are quite small so result is '' and f.extrabuf
            # contains the whole page content
            if result or getattr(stream, 'extrabuf', None):
                try:
                    result += stream.extrabuf
                finally:
                    break
            else:
                raise
    return result


def is_gzipped(response):
    """Return True if the response is gzipped, or False otherwise"""
    content_type = response.headers.get('Content-Type', b'')
    return content_type in (b'application/x-gzip', b'application/gzip')
